import{_ as t,H as a,f as p,i as _}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"新书 | 《裂变：秒懂人工智能的基础课》","description":"","frontmatter":{},"headers":[],"relativePath":"人工智能基础课/新书-《裂变：秒懂人工智能的基础课》.md","filePath":"人工智能基础课/新书-《裂变：秒懂人工智能的基础课》.md","lastUpdated":1779818127000}'),s={name:"人工智能基础课/新书-《裂变：秒懂人工智能的基础课》.md"};function n(r,e,i,o,c,l){return a(),p("div",null,[...e[0]||(e[0]=[_('<h1 id="新书-《裂变-秒懂人工智能的基础课》" tabindex="-1">新书 | 《裂变：秒懂人工智能的基础课》 <a class="header-anchor" href="#新书-《裂变-秒懂人工智能的基础课》" aria-label="Permalink to &quot;新书 | 《裂变：秒懂人工智能的基础课》&quot;">​</a></h1><p>你好，我是王天一，今天发一个彩蛋：我的新书终于跟你见面了！</p><p>这本书脱胎于我们的专栏，书名是《裂变：秒懂人工智能的基础课》。</p><p>我们的专栏共40期，在三个多月的时间里，我和你一起学习了人工智能领域最关键的基础知识，包括数学基础、机器学习、神经网络、深度学习以及深度学习之外的人工智能，还讨论了人工智能在视觉、语音、对话系统和机器翻译领域中的应用。</p><p>这三个多月里，有五千多位同学参与到我们的基础课当中，给予了很多高质量的反馈，因此这本书其实是我们共同创作的成果。</p><p>书的框架和专栏的模块保持一致，在此基础上补充了参考文献，对排版也做了调整，以期给你最佳的阅读体验。希望这本书能够完成这样一个使命： <strong>复习专栏内容，打造人工智能的知识架构</strong>。</p><p>我们的课程是基础课，通过最低程度使用繁杂的公式来让内容通俗易懂。但这可不代表内容简单，恰恰相反，专栏的每一个模块都有其深度，需要反复复习，才能达到通透掌握的程度。</p><p>这里我引用老师木给本书写的一段推荐语：“读者可以把这本书当成一个索引去了解人工智能的基本原理，若仍无法满足好奇心的话，再去原始文献中找到细节，甚至找到源代码和数据集实践，这是一个由薄到厚的过程；当对磅礴繁杂的内容融会贯通之后，发现机器学习的要义已被这一本薄书涵盖了，真是奇妙无比。”</p><p>这本书就是一份简历、一份提纲，勾勒出人工智能的基本框架，是一个“薄”的开始，引领你走过一个“厚”的过程，再回来后，就一定会有更高远的视野和更深刻的洞见。那个时候，你一定会对老师木所说的“奇妙无比”心领神会！</p><p>所以，你完全可以把这本书当作这门课程的课本，复习的时候，配合音频，根据自己的掌握情况，有针对性地练习，这也是现在大家都熟悉的“刻意练习”的关键。要知道，刻意练习不是简单的重复，而是针对自己似懂非懂、还没完全掌握的内容，刻意去训练提升自己。</p><p>最后，作为对这个专栏最好的沉淀，欢迎你阅读这本书，我们共同努力的结晶！</p><p>6月13~15日首发，三天限时优惠。《裂变：秒懂人工智能的基础课》新书，原价￥59，现价￥49！你可以从发现页进入极客商城后进行购买。</p><p>体贴的运营同学还给你发了短信，可以领取5元礼券（与优惠价同享），有效期到6月30日，提醒你抓紧使用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD%E5%9F%BA%E7%A1%80%E8%AF%BE/images/9118/4acbebba2566be583d0254659ef68fa1.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD%E5%9F%BA%E7%A1%80%E8%AF%BE/images/9118/4acbebba2566be583d0254659ef68fa1.jpg" alt=""></a></p>',14)])])}const b=t(s,[["render",n]]);export{E as __pageData,b as default};
